import{_ as e,a as o}from"./chunks/rt_dt.DBwJICWL.js";import{_ as n,o as r,c as a,a0 as i}from"./chunks/framework.akKRIpjQ.js";const f=JSON.parse('{"title":"05 · Tension Conversion","description":"","frontmatter":{},"headers":[],"relativePath":"guide/05-tension-conversion.md","filePath":"guide/05-tension-conversion.md"}'),s={name:"guide/05-tension-conversion.md"};function d(h,t,l,c,u,g){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_05-·-tension-conversion" tabindex="-1">05 · Tension Conversion <a class="header-anchor" href="#_05-·-tension-conversion" aria-label="Permalink to &quot;05 · Tension Conversion&quot;">​</a></h1><blockquote><p>Feature 4 of 4. Convert between <strong>dynamic tension (DT)</strong> and <strong>reference tension (RT)</strong>, and between <strong>lbs</strong> and <strong>kg</strong>. Press <strong><code>Use this tension → log stringing</code></strong> to jump straight into <a href="./04-stringing-log.html">04 · Stringing log</a> with your result pre-filled.</p></blockquote><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>A standalone screen on the Home tab (&quot;Tension conversion&quot; top card) and on <code>Rackets</code> tab. Three conversion modes (toggle inside one card):</p><ul><li><strong>DT → RT</strong> — enter a DT (dynamic tension) from your stringing machine → get the equivalent RT (reference tension / static tension) in lbs &amp; kg</li><li><strong>RT → DT</strong> — enter RT in lbs → get the DT value back</li><li><strong>lbs ⇄ kg</strong> — pull-force unit swap</li></ul><p>Each result screen has:</p><ul><li>The computed pair</li><li>A confidence note (&quot;estimated within ±1 lb&quot;)</li><li><strong><code>Use this tension → log stringing</code></strong> button — drops you into the <strong>Stringing log → Add record</strong> form (<a href="./04-stringing-log.html">chapter 04</a>) with everything filled in</li></ul><h2 id="head-size-buckets-used-by-dt-⇄-rt" tabindex="-1">Head size buckets (used by DT ⇄ RT) <a class="header-anchor" href="#head-size-buckets-used-by-dt-⇄-rt" aria-label="Permalink to &quot;Head size buckets (used by DT ⇄ RT)&quot;">​</a></h2><p>The DT ⇄ RT conversion in this App uses <strong>3 head-size buckets</strong> (matching the ERT300 reference machine&#39;s DT anchor table). Pick the bucket that matches your racket — that&#39;s all the App needs.</p><table tabindex="0"><thead><tr><th>Bucket</th><th>sq.in.</th><th>cm²</th><th>Common racket types</th></tr></thead><tbody><tr><td><strong>MID</strong></td><td>83–94</td><td>540–610</td><td>Control / small head (tour-style frames)</td></tr><tr><td><strong>MID+</strong></td><td>95–105</td><td>611–680</td><td>Most modern rackets (default)</td></tr><tr><td><strong>OVER</strong></td><td>106–115</td><td>681–740</td><td>Oversize / recreational</td></tr></tbody></table><blockquote><p>The bucket label in the picker follows your <strong>area-unit preference</strong> — sq.in. for imperial users, cm² for metric. Switch in <a href="./06-settings-faq.html">Settings → Area unit</a>. cm² ↔ sq.in. is <strong>not</strong> auto-converted (the bucket boundaries are not perfectly aligned).</p></blockquote><p>The DT ⇄ RT calculation itself uses a per-bucket lookup table from USRSA public bulletins; bucket selection is the only head-size input the App asks for.</p><h2 id="dt-→-rt-the-headline-feature" tabindex="-1">DT → RT (the headline feature) <a class="header-anchor" href="#dt-→-rt-the-headline-feature" aria-label="Permalink to &quot;DT → RT (the headline feature)&quot;">​</a></h2><img src="'+e+'" alt="DT → RT conversion" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Most stringing machines report either DT or RT. Switching the unit in the App gives you the equivalent in the other system.</p><h3 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Original tension</td><td>empty</td><td>Number + unit (lbs or kg)</td></tr><tr><td>Direction</td><td>DT → RT (default)</td><td>Or RT → DT</td></tr><tr><td>Bed type</td><td>Polyester (default)</td><td>Polyester / multifilament / natural gut — affects the conversion factor</td></tr><tr><td>Head size bucket</td><td>MID+ (default)</td><td>3 buckets — see <a href="#head-size-buckets-used-by-dt--rt">Head size buckets</a></td></tr></tbody></table><h3 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Example</th><th>Result</th></tr></thead><tbody><tr><td>DT 60 lbs polyester on MID+</td><td>RT 56.4 lbs</td></tr><tr><td>RT 56 lbs multifilament on MID+</td><td>DT 58.7 lbs</td></tr></tbody></table><blockquote><p>The conversion uses a per-bed, per-bucket lookup table. Factors were derived from USRSA public bulletins.</p></blockquote><h3 id="when-not-to-trust-the-conversion" tabindex="-1">When <strong>not</strong> to trust the conversion <a class="header-anchor" href="#when-not-to-trust-the-conversion" aria-label="Permalink to &quot;When **not** to trust the conversion&quot;">​</a></h3><ul><li><strong>Bed type unknown</strong> — if you can&#39;t confirm the string is polyester / multifilament / gut, the conversion can be off by ±2 lbs</li><li><strong>Racket on the bucket boundary</strong> — e.g. a 95 in² racket sits right on the MID / MID+ border; pick the bucket that matches your manufacturer&#39;s spec sheet</li><li><strong>Mixed strings</strong> (hybrid main / cross) — each side needs its own conversion; the App handles them as separate entries</li></ul><h2 id="dt-⇄-rt-conversion-table-quick-reference" tabindex="-1">DT ⇄ RT conversion table (quick reference) <a class="header-anchor" href="#dt-⇄-rt-conversion-table-quick-reference" aria-label="Permalink to &quot;DT ⇄ RT conversion table (quick reference)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bucket</th><th>Polyester</th><th>Multifilament</th><th>Natural gut</th></tr></thead><tbody><tr><td>MID (83–94 in²)</td><td>0.94</td><td>0.97</td><td>0.99</td></tr><tr><td>MID+ (95–105 in²)</td><td>0.93</td><td>0.96</td><td>0.98</td></tr><tr><td>OVER (106–115 in²)</td><td>0.91</td><td>0.94</td><td>0.96</td></tr></tbody></table><blockquote><p>Factor = <code>RT / DT</code>. To convert DT → RT, multiply by the factor; to convert RT → DT, divide.</p></blockquote><h2 id="rt-⇄-dt-the-other-direction" tabindex="-1">RT ⇄ DT (the other direction) <a class="header-anchor" href="#rt-⇄-dt-the-other-direction" aria-label="Permalink to &quot;RT ⇄ DT (the other direction)&quot;">​</a></h2><img src="'+o+`" alt="RT → DT conversion" style="max-width:320px;border-radius:12px;margin:12px 0;"><p>Reverse of the above. Same inputs, opposite direction. Pick this when the stringing machine gave you RT and your training data is in DT (or vice-versa).</p><h2 id="lbs-⇄-kg" tabindex="-1">lbs ⇄ kg <a class="header-anchor" href="#lbs-⇄-kg" aria-label="Permalink to &quot;lbs ⇄ kg&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kg = lbs × 0.4536</span></span>
<span class="line"><span>lbs = kg × 2.2046</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Pull (lbs / kg)</th><th>Style</th></tr></thead><tbody><tr><td>40 / 18.1</td><td>Very loose (recreational)</td></tr><tr><td>50 / 22.7</td><td>Loose</td></tr><tr><td>55 / 24.9</td><td>Standard male</td></tr><tr><td>60 / 27.2</td><td>Standard male, tighter</td></tr><tr><td>65 / 29.5</td><td>Tight</td></tr><tr><td>70 / 31.8</td><td>Very tight (pro)</td></tr></tbody></table><blockquote><p>&quot;lbs&quot; here is <strong>pounds-force</strong> (lbf). Players just say &quot;50 pounds&quot; colloquially.</p></blockquote><p>The lbs ⇄ kg conversion is offered alongside DT ⇄ RT on the same screen; toggle a switch to flip modes.</p><hr><h2 id="⤳-use-this-tension-→-log-stringing" tabindex="-1">⤳ Use this tension → log stringing <a class="header-anchor" href="#⤳-use-this-tension-→-log-stringing" aria-label="Permalink to &quot;⤳ Use this tension → log stringing&quot;">​</a></h2><p>After any of the conversions above, the bottom of the result screen shows a large button:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Use this tension → log stringing ]</span></span></code></pre></div><h3 id="what-it-does-1" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does-1" aria-label="Permalink to &quot;What it does&quot;">​</a></h3><ul><li>Picks the current racket (or asks you to pick from the list if no context)</li><li>Pre-fills the <strong>Stringing log → Add record</strong> form (<a href="./04-stringing-log.html">chapter 04</a>): <ul><li>Date = today</li><li>Tension main = the DT you converted (in lbs, after unit conversion)</li><li>Tension cross = inherits from the racket profile</li><li>Source = <code>From Tension conversion</code></li></ul></li><li>Marks the record&#39;s <strong>source</strong> so that future &quot;this came from the converter&quot; is verifiable</li></ul><h3 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h3><ul><li>You just got your racket back from the stringer and the machine showed DT 60 lbs</li><li>You want to record this restring in the App to drive the reminder</li><li>Instead of typing the number again, tap the handoff button</li></ul><h3 id="when-not-to-use-it" tabindex="-1">When <strong>not</strong> to use it <a class="header-anchor" href="#when-not-to-use-it" aria-label="Permalink to &quot;When **not** to use it&quot;">​</a></h3><ul><li>You&#39;re shopping for tension (just curious what RT 56 lbs feels like as DT 59)</li><li>You&#39;re converting an old string job for reference (the source tag stays on but the date needs fixing)</li></ul><h3 id="edit-before-save" tabindex="-1">Edit before save <a class="header-anchor" href="#edit-before-save" aria-label="Permalink to &quot;Edit before save&quot;">​</a></h3><p>The pre-filled values are editable — change anything you want before hitting <code>Save</code>. The source tag stays as <code>From Tension conversion</code> either way.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>❌ <strong>Ignores stringer accuracy</strong>: any stringing machine drifts ± 2 lbs</li><li>❌ <strong>Ignores temperature / humidity</strong>: after a few hours at 35 °C, the bed drops ~2 lbs</li><li>❌ <strong>Bed type confidence</strong>: &quot;I&#39;m not sure what was strung&quot; → the result is in a wide band; record the actual string model after the fact at the form</li></ul><h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><h3 id="can-i-record-stringing-without-going-through-this" tabindex="-1">Can I record stringing without going through this? <a class="header-anchor" href="#can-i-record-stringing-without-going-through-this" aria-label="Permalink to &quot;Can I record stringing without going through this?&quot;">​</a></h3><p>Yes — the Stringing log is independent. The handoff is just a shortcut.</p><h3 id="do-the-lb-⇄-kg-and-dt-⇄-rt-factors-ever-change" tabindex="-1">Do the LB ⇄ KG and DT ⇄ RT factors ever change? <a class="header-anchor" href="#do-the-lb-⇄-kg-and-dt-⇄-rt-factors-ever-change" aria-label="Permalink to &quot;Do the LB ⇄ KG and DT ⇄ RT factors ever change?&quot;">​</a></h3><p>The factor table is bundled in the App and updates with each release. We don&#39;t fetch new factors at runtime — this keeps conversions reproducible.</p><h3 id="what-if-i-convert-an-old-restring" tabindex="-1">What if I convert an old restring? <a class="header-anchor" href="#what-if-i-convert-an-old-restring" aria-label="Permalink to &quot;What if I convert an old restring?&quot;">​</a></h3><p>Tap <strong>Use this tension → log stringing</strong>, change the date in the form, save. The source tag stays as &quot;From Tension conversion&quot; but the date reflects when it actually happened.</p><h2 id="where-do-these-numbers-come-from" tabindex="-1">Where do these numbers come from? <a class="header-anchor" href="#where-do-these-numbers-come-from" aria-label="Permalink to &quot;Where do these numbers come from?&quot;">​</a></h2><p>DT ⇄ RT factors use a per-bed, per-headsize lookup derived from USRSA public bulletins and stringing-machine manufacturer data. Each has a source; the App does not fetch updated values at runtime.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./04-stringing-log.html">04 · Stringing log</a> — where the handoff lands</li><li><a href="./03-racquets.html">03 · Rackets</a> — the racket profile that the handoff depends on</li></ul>`,58)])])}const m=n(s,[["render",d]]);export{f as __pageData,m as default};
